    public void checkFileExtension(String path, EPUBVersion version, Report report, EPUBProfile profile) {
        try (FileReader reader = new FileReader(path)) {

            // Check if the file has an .epub extension
            String fileExtension = URLUtils.getFileName(path).toString();
            if (!fileExtension.equals(".epub")) {
                throw new RuntimeException("The file must have an .epub extension");
            }

            // Write a message to the report indicating that the file is a valid .epub file
            report.addMessage(new Messages.MessageDictionaryDumper().getMessages().findKeyByString("EPUBFILETYPE"), "The file has an .epub extension");

        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public void checkFileMIMEType(String path, EPUBVersion version, Report report, EPUBProfile profile) {
        try (FileReader reader = new FileReader(path)) {

            // Check if the file has a valid MIME type
            String mimeType = URLUtils.getFileName(path).toString();
            if (!mimeType.startsWith("application/x-adobe-epub+xml")) {
                throw new RuntimeException("The file must have a valid MIME type");
            }

        } catch (IOException e) {
            throw new RuntimeException(e);
